     1	/**
     2	 * THE generic resource-visibility compiler — gates connector-sourced `events`
     3	 * (GitHub issues/PRs, Linear issues, …) by RESOURCE membership, the same way
     4	 * `./channel-visibility` gates Slack chat by channel membership, but at the
     5	 * `events` read seam and for ANY resource type at once.
     6	 *
     7	 * Rule, composed AFTER the per-connection visibility gate (they AND together),
     8	 * mirroring the three-state enforcement split `getConnectionEnforcement` /
     9	 * `./channel-visibility` apply so the two gates can never drift:
    10	 *   - an event on a connection that was NEVER graphed (no `authz_source_acl_state`
    11	 *     row) is unconstrained here — the per-connection gate already decided it and
    12	 *     an absent graph must never silently hide data;
    13	 *   - an event on an ENFORCED connection (`acl_support='full'`,
    14	 *     `freshness_state='fresh'`, synced within the freshness window) is visible
    15	 *     ONLY when the requester is `member_of` one of the RESOURCE entities the
    16	 *     event is linked to (`events.entity_ids`), where "resource" = an entity whose
    17	 *     type is `$resource`. Scoped so the coarse person→`company` (org)
    18	 *     `member_of` edge never satisfies it — org membership must NOT grant
    19	 *     repo-level read;
    20	 *   - an event on an onboarded-but-STALE connection (a row exists but is
    21	 *     partial/failed/stale/aged-out — i.e. NOT in the enforced set) FAILS CLOSED:
    22	 *     neither the not-graphed passthrough nor the enforced membership branch
    23	 *     matches, so its resource-linked events are dropped rather than served on
    24	 *     stale membership. Once a connection is graphed, it never falls back to the
    25	 *     legacy per-connection fence — a stalled sync hides data, it does not leak it.
    26	 *
    27	 * Fail-closed: a headless/null principal on an enforced connection, a
    28	 * non-interaction event linked to no resource the requester belongs to, or any
    29	 * event on a stale connection is dropped.
    30	 *
    31	 * Interaction events (`interaction_type <> 'none'`: approvals, suggestions)
    32	 * are instead readable by any ORGANIZATION member, in every graph state.
    33	 * They are server-authored workflow state, not synced resource content: an
    34	 * operation's approval card is stamped with the connection it acts THROUGH but
    35	 * may have no resource entity link, so the membership branch could never match
    36	 * and the gate hid pending approvals from everyone, org admins included (prod
    37	 * run 757649). The arm is deliberately freshness-independent — hiding an
    38	 * approval because the ACL sync stalled would silently wedge the operation it
    39	 * gates, and the `member`-row check it relies on is live data, not the synced
    40	 * graph. It still requires an organization membership row, so headless and
    41	 * public non-member reads gain nothing, and connector sync never writes
    42	 * `interaction_type`, so no synced resource content can ride the exemption.
    43	 * The per-connection visibility gate always still applies in front. Generic
    44	 * across sources — GitHub repos and Linear teams gate identically; a new
    45	 * source needs only a registry entry (`./sources`) plus its connector stamping
    46	 * the resource identity on its events so they link to the resource entity.
    47	 */
    48	
    49	import { ACL_RESOURCE_TYPE_SLUG } from '@lobu/connector-sdk';
    50	import { aclStateExistsSelectSql, enforcedConnectionsSelectSql } from './acl-state.js';
    51	import type { AuthzScope } from './scope.js';
    52	
    53	/** Sole ACL resource type slug, inlined as a SQL string literal (constant). */
    54	const RESOURCE_TYPE_SQL = `'${ACL_RESOURCE_TYPE_SLUG}'`;
    55	
    56	/**
    57	 * Predicate for a table holding events (alias has `connection_id` + `entity_ids`).
    58	 * Binds two params from `baseParamIndex`: the org id and the principal. Returns an
    59	 * `AND (...)` fragment (no leading space). Compose alongside
    60	 * `compileConnectionFkVisibility` at the same seam.
    61	 */
    62	export function compileResourceVisibility(
    63	  scope: AuthzScope,
    64	  baseParamIndex: number,
    65	  tableAlias: string,
    66	): { sql: string; params: Array<string | null> } {
    67	  const orgParam = `$${baseParamIndex}::text`;
    68	  const userParam = `$${baseParamIndex + 1}::text`;
    69	
    70	  // `events.connection_id` is the bigint `connections.id`, but
    71	  // `authz_source_acl_state.connection_id` is text — the ACL sync stamps it as
    72	  // `String(connections.id)` (see `github-acl-sync` → `buildAccessGraph`). Cast
    73	  // `events.connection_id::text` so BOTH the "is this connection graphed?" check
    74	  // and the "is it enforced?" check compare on the SAME key.
    75	  //
    76	  // Three-state split (mirrors `getConnectionEnforcement`), NOT a bare
    77	  // `NOT IN (enforced)`:
    78	  //   1. no ACL row for the connection → passthrough (never graphed → legacy fence);
    79	  //   2. row is enforced (in the fresh-enforced set) → require resource membership;
    80	  //   3. row exists but is NOT enforced (stale/partial/failed/aged-out) → neither
    81	  //      branch matches → FAIL CLOSED. A bare `NOT IN (enforced)` would make (3)
    82	  //      true and leak stale-connection events to non-members — the hole this fix
    83	  //      closes, matching the channel gate.
    84	  // Server-authored interaction events sit OUTSIDE the split: any organization
    85	  // member may read them in every graph state (see module doc).
    86	  const sql = `AND (
    87	      ${tableAlias}.connection_id IS NULL
    88	      OR ${tableAlias}.connection_id::text NOT IN (${aclStateExistsSelectSql(orgParam)})
    89	      OR (${tableAlias}.interaction_type <> 'none'
    90	      AND EXISTS (
    91	        SELECT 1
    92	        FROM public."member" om
    93	        WHERE om."organizationId" = ${orgParam}
    94	          AND om."userId" = ${userParam}
    95	      ))
    96	      OR (${tableAlias}.connection_id::text IN (${enforcedConnectionsSelectSql(orgParam)})
    97	      AND EXISTS (
    98	        SELECT 1
    99	        FROM public.entity_relationships rr
   100	        JOIN public.entity_relationship_types rt
   101	          ON rt.id = rr.relationship_type_id
   102	         AND rt.organization_id = rr.organization_id
   103	         AND rt.slug = 'member_of'
   104	        JOIN public.entities re
   105	          ON re.id = rr.to_entity_id
   106	         AND re.organization_id = rr.organization_id
   107	         AND re.deleted_at IS NULL
   108	        JOIN public.entity_types ret
   109	          ON ret.id = re.entity_type_id
   110	         AND ret.organization_id = re.organization_id
   111	         AND ret.slug = ${RESOURCE_TYPE_SQL}
   112	        WHERE rr.organization_id = ${orgParam}
   113	          AND rr.deleted_at IS NULL
   114	          AND rr.to_entity_id = ANY(${tableAlias}.entity_ids)
   115	          AND rr.from_entity_id = (
   116	            SELECT mei.entity_id
   117	            FROM public.entity_identities mei
   118	            JOIN public.entities me
   119	              ON me.id = mei.entity_id
   120	             AND me.organization_id = mei.organization_id
   121	             AND me.deleted_at IS NULL
   122	            JOIN public.entity_types met
   123	              ON met.id = me.entity_type_id
   124	             AND met.organization_id = me.organization_id
   125	             AND met.slug = '$member'
   126	            WHERE mei.organization_id = ${orgParam}
   127	              AND mei.namespace = 'auth_user_id'
   128	              AND mei.identifier = ${userParam}
   129	              AND mei.source_connector = 'auth:signup'
   130	              AND mei.deleted_at IS NULL
   131	            LIMIT 1
   132	          )
   133	      ))
   134	    )`;
   135	  return { sql, params: [scope.organizationId, scope.principal] };
   136	}


