     1	#!/usr/bin/env node
     2	// Guard: the per-user connection-visibility READ-SEAM gate must live in exactly
     3	// one place — the compiler at packages/server/src/authz/connection-visibility.ts.
     4	//
     5	// The authorization guarantee (M0/M1) is that connection-sourced data never
     6	// reaches a user beyond what that user can see in the source system. Every read
     7	// seam that exposes connection-sourced rows (the SQL buildScopedQuery, recall's
     8	// search/list paths, get_content) must scope them through the ONE compiler
     9	// (`compileConnectionFkVisibility`), not re-derive the predicate inline. A
    10	// re-derived copy is how the gate silently drifts: a finding leaks because one
    11	// copy was never updated.
    12	//
    13	// The precise, low-false-positive signal for a re-derivation is the FK subquery
    14	// SHAPE itself:
    15	//
    16	//   ... <table>.connection_id [IS NULL OR ...] IN ( SELECT ... FROM connections
    17	//        ... WHERE ... visibility ... )
    18	//
    19	// i.e. a table is filtered to "connections this principal may see" via a
    20	// `connection_id IN (SELECT ... FROM connections ... visibility ...)` subquery.
    21	// That shape is the read-seam gate. It is DISTINCT from legitimate connection
    22	// MANAGEMENT code (manage_connections CRUD, rest-api listing, connector
    23	// pushdown), which filters the `connections` row directly (`c.visibility = 'org'
    24	// OR c.created_by = ...`) and never builds the FK subquery — so those are not
    25	// flagged.
    26	//
    27	// HONEST GAP: a re-derivation that avoids this exact subquery shape (e.g. a JOIN
    28	// instead of `IN (SELECT ...)`, or building the connection-id set in JS) is NOT
    29	// caught here. The durable backstops for those are the per-seam deny-tests
    30	// (merge blocker) and reviewer attention. Escape hatch: put
    31	// `connection-visibility-ok` in a comment on or just above a genuinely-safe
    32	// occurrence.
    33	//
    34	// No DB, no build — pure static text analysis.
    35	// Run: `node scripts/check-connection-visibility-compiler.mjs`
    36	
    37	import { readdirSync, readFileSync, statSync } from "node:fs";
    38	import { dirname, join, relative, resolve } from "node:path";
    39	import { fileURLToPath } from "node:url";
    40	
    41	const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
    42	const SERVER_SRC = join(REPO_ROOT, "packages/server/src");
    43	
    44	// The one place the FK read-seam gate is allowed to live.
    45	const COMPILER_FILE = join(SERVER_SRC, "authz/connection-visibility.ts");
    46	
    47	// The FK read-seam-gate subquery shape (case-insensitive, across newlines):
    48	// a table's connection_id constrained by a SELECT over the connections table
    49	// that filters on `visibility`. The bounded `[^;]{0,N}` windows keep it to a
    50	// single statement and avoid matching across unrelated SQL.
    51	const FK_GATE =
    52	  /connection_id\b[^;]{0,80}\bIN\b[^;]{0,200}?\bconnections\b[^;]{0,240}?visibility/is;
    53	
    54	const ESCAPE_HATCH = "connection-visibility-ok";
    55	
    56	/** Recursively collect *.ts files under dir, excluding tests. */
    57	function collectTsFiles(dir) {
    58	  const out = [];
    59	  for (const name of readdirSync(dir)) {
    60	    const full = join(dir, name);
    61	    const st = statSync(full);
    62	    if (st.isDirectory()) {
    63	      if (name === "__tests__" || name === "node_modules") continue;
    64	      out.push(...collectTsFiles(full));
    65	    } else if (name.endsWith(".ts") && !name.endsWith(".test.ts")) {
    66	      out.push(full);
    67	    }
    68	  }
    69	  return out;
    70	}
    71	
    72	const violations = [];
    73	for (const file of collectTsFiles(SERVER_SRC)) {
    74	  if (file === COMPILER_FILE) continue;
    75	  const src = readFileSync(file, "utf8");
    76	  const m = FK_GATE.exec(src);
    77	  if (!m) continue;
    78	  // Allow an explicit escape hatch in a comment near the match.
    79	  const lineNo = src.slice(0, m.index).split("\n").length;
    80	  const lines = src.split("\n");
    81	  const nearby = [lines[lineNo - 2], lines[lineNo - 1], lines[lineNo]].join(
    82	    "\n"
    83	  );
    84	  if (nearby.includes(ESCAPE_HATCH)) continue;
    85	  violations.push({ file: relative(REPO_ROOT, file), lineNo });
    86	}
    87	
    88	if (violations.length > 0) {
    89	  console.error(
    90	    "\n✖ connection-visibility read-seam gate re-derived outside the compiler:\n"
    91	  );
    92	  for (const v of violations) {
    93	    console.error(`  ${v.file}:${v.lineNo}`);
    94	  }
    95	  console.error(
    96	    "\nThe FK read-seam gate (connection_id IN (SELECT ... FROM connections ... visibility ...))\n" +
    97	      "must come from compileConnectionFkVisibility() in\n" +
    98	      "  packages/server/src/authz/connection-visibility.ts\n" +
    99	      "so the per-user visibility rule lives in one place. Route this read through\n" +
   100	      "the compiler (or buildConnectionVisibilityClause, which adapts to it). If this\n" +
   101	      `is genuinely safe, add a "${ESCAPE_HATCH}" comment on the line.\n`
   102	  );
   103	  process.exit(1);
   104	}
   105	
   106	console.log(
   107	  "✓ connection-visibility read-seam gate is compiler-only (no re-derivations)"
   108	);


