     1	/**
     2	 * Execute SQL data sources defined in a JSON view template.
     3	 *
     4	 * Queries run against a virtual schema of org-scoped CTEs. Table references
     5	 * in user queries are resolved to:
     6	 *   - Core tables (entities, events, connections, watchers, event_classifications)
     7	 *     → CTE with organization_id filter
     8	 *   - Any other name → treated as an entity_type slug, filtered from entities
     9	 *
    10	 * Security:
    11	 *   - SQL parsed via @polyglot-sql/sdk to extract ALL table references
    12	 *   - Schema-qualified references (e.g. public.user) rejected outright
    13	 *   - Every table ref gets a CTE with org-scoping baked in
    14	 *   - READ ONLY transaction + timeout via sql.begin()
    15	 *   - FORBIDDEN_OPS regex as additional safeguard
    16	 */
    17	
    18	import { Dialect, ast, parse as parseSql } from '@polyglot-sql/sdk';
    19	import { type DbClient, pgTextArray } from '../db/client';
    20	import logger from './logger';
    21	import { useLinkedOrgScope } from './linked-org-ids';
    22	import {
    23	  compileConnectionFkVisibility,
    24	  compileConnectionRowVisibility,
    25	} from '../authz/connection-visibility';
    26	import { compileChannelMessagesVisibility } from '../authz/channel-messages-visibility';
    27	import { compileResourceVisibility } from '../authz/resource-visibility';
    28	import type { AuthzScope } from '../authz/scope';
    29	import {
    30	  ADMIN_ONLY_QUERYABLE_TABLES,
    31	  buildColumnList,
    32	  type ColumnDef,
    33	  formatUnknownTablesError,
    34	  QUERYABLE_TABLE_NAMES,
    35	  RETIRED_RELATION_NAMES,
    36	  SAFE_COLUMN_DEFS,
    37	  validateTableQuery,
    38	} from './table-schema';
    39	import { getErrorMessage } from "@lobu/core";
    40	
    41	/** A named SQL data source: { name, query } or keyed as Record<string, { query }> */
    42	export type DataSourceInput =
    43	  | Record<string, { query: string }>
    44	  | Array<{ name: string; query: string }>;
    45	
    46	export interface DataSourceContext {
    47	  organizationId: string;
    48	  /**
    49	   * The requesting user. When set, the events CTE additionally intersects with
    50	   * per-user connection visibility (visibility='org' OR created_by=userId) so
    51	   * query_sql / metrics / client.query don't leak other users' private-connection
    52	   * data — matching what search_memory/get_content already enforce.
    53	   */
    54	  userId?: string | null;
    55	  /** When set, events CTE filters to events belonging to any of these entities */
    56	  entityIds?: number[];
    57	  query?: Record<string, string>;
    58	  /** When set, events CTE is filtered to this time window (incremental mode) */
    59	  windowStart?: string;
    60	  windowEnd?: string;
    61	  /**
    62	   * When set, the events CTE drops rows this Behavior produced, except human
    63	   * canvas corrections (`semantic_type='canvas_state'` with
    64	   * `metadata.correction`). Set it for a Behavior's own source execution and
    65	   * nowhere else — a generic reader (`query_sql`, entity templates) must still
    66	   * see Behavior-produced events.
    67	   */
    68	  excludeProducedByBehaviorId?: number | null;
    69	}
    70	
    71	/** Operations that bypass READ ONLY transactions or have side-effects. */
    72	const FORBIDDEN_OPS = /\b(COPY|IMPORT|PRAGMA|CALL)\b/i;
    73	const MAX_ROWS = 1000;
    74	const QUERY_TIMEOUT_MS = 5000;
    75	
    76	type SqlNode = ast.Expression;
    77	
    78	/** Strip {{...}} template placeholders to a literal so the parser doesn't choke. */
    79	function stripPlaceholders(sql: string): string {
    80	  return sql.replace(/\{\{\w+(?:\.\w+)?\}\}/g, '0');
    81	}
    82	
    83	/** Parse to the top-level statement node, or undefined when the SQL won't parse. */
    84	function parseRoot(sql: string): SqlNode | undefined {
    85	  const res = parseSql(stripPlaceholders(sql), Dialect.PostgreSQL);
    86	  if (!res.success || !res.ast) return undefined;
    87	  return (Array.isArray(res.ast) ? res.ast[0] : res.ast) as SqlNode | undefined;
    88	}
    89	
    90	/** Pull a bare identifier string out of polyglot's `{ name, quoted }` shapes. */
    91	function identName(value: unknown): string | null {
    92	  if (typeof value === 'string') return value;
    93	  if (value && typeof value === 'object') {
    94	    const o = value as Record<string, unknown>;
    95	    if (typeof o.name === 'string') return o.name;
    96	    if (o.name && typeof o.name === 'object') return identName(o.name);
    97	    if (o.this) return identName(o.this);
    98	  }
    99	  return null;
   100	}
   101	
   102	/**
   103	 * Collect every schema-qualified table reference (`schema.table`) in the parsed
   104	 * tree by recursing the RAW AST node graph.
   105	 *
   106	 * Security-critical: org-scoping shadows UNQUALIFIED table names with CTEs, so a
   107	 * schema-qualified ref (`public.connections`, `pg_catalog.*`) bypasses scoping
   108	 * and reads every org's rows. polyglot's `getTables`/`walk`/`findByType` only
   109	 * surface the FIRST `FROM` table — they do NOT descend into JOINs or
   110	 * sub-selects — so a qualified table in a join or subquery would slip past a
   111	 * node-enumeration check. A raw recursion over the node graph is the only
   112	 * reliable way to see them all. A polyglot table-ref node is shaped
   113	 * `{ name, schema, catalog, ... }`; `schema` is null when unqualified.
   114	 *
   115	 * Iterative (stack) traversal, NOT recursion: a recursion depth-cap would
   116	 * fail OPEN — a deeply-nested `public.oauth_tokens` past the cap would slip
   117	 * past and bypass scoping. The `seen` set bounds the walk on cyclic graphs.
