    42	 * runtime id], `channel_id` [bare], `organization_id`). Binds two params from
    43	 * `baseParamIndex`: the org id and the principal. Returns an `AND (...)` fragment
    44	 * (no leading space).
    45	 *
    46	 * `channel_messages.connection_id` and `authz_source_acl_state.connection_id` are
    47	 * BOTH the runtime connection id (see `slack-acl-sync`/`persistChannelMessage`),
    48	 * so the enforced-set membership check compares like-for-like. The channel entity
    49	 * is team-scoped (`T:C`), so the team is resolved from the row's connection
    50	 * (`external_tenant_id` / `config.chatMetadata.teamId`), matched by slug via both
    51	 * the BYO (`agentconn-<id>`) and slack-install (`<id>`) namespaces.
    52	 */
    53	export function compileChannelMessagesVisibility(
    54	  scope: AuthzScope,
    55	  baseParamIndex: number,
    56	  tableAlias: string,
    57	  // The registered chat platforms whose channel gate is emitted. Defaults to the
    58	  // production registry; injectable so the multi-platform OR (≥2 branches) can be
    59	  // exercised without registering a real second connector.
    60	  identities: ChannelReadIdentity[] = CHANNEL_READ_IDENTITIES,
    61	): { sql: string; params: Array<string | null> } {
    62	  const orgParam = `$${baseParamIndex}::text`;
    63	  const userParam = `$${baseParamIndex + 1}::text`;
    64	
    65	  // The requester's `$member` entity, resolved on the auth-signup claim only
    66	  // (same guard as compileResourceVisibility — server-written, unforgeable).
    67	  const requesterMemberSubquery = `(
    68	    SELECT mei.entity_id
    69	    FROM public.entity_identities mei
    70	    JOIN public.entities me
    71	      ON me.id = mei.entity_id
    72	     AND me.organization_id = mei.organization_id
    73	     AND me.deleted_at IS NULL
    74	    JOIN public.entity_types met
    75	      ON met.id = me.entity_type_id
    76	     AND met.organization_id = me.organization_id
    77	     AND met.slug = '$member'
    78	    WHERE mei.organization_id = ${orgParam}
    79	      AND mei.namespace = 'auth_user_id'
    80	      AND mei.identifier = ${userParam}
    81	      AND mei.source_connector = 'auth:signup'
    82	      AND mei.deleted_at IS NULL
    83	    LIMIT 1
    84	  )`;
    85	
    86	  // The tenant/team the channel key is scoped by, resolved from the row's
    87	  // connection (platform-neutral): the row's own team_id, else the connection's
    88	  // external tenant id / chatMetadata teamId. Passed as the team expression to
    89	  // each platform's channel-key builder.
    90	  const teamExpr = `COALESCE(
    91	    ${tableAlias}.team_id,
    92	    conn.external_tenant_id,
    93	    conn.config->'chatMetadata'->>'teamId'
    94	  )`;
    95	
    96	  // One channel-membership EXISTS branch per registered chat platform: the
    97	  // requester is `member_of` the `$resource` entity keyed by THIS platform's
    98	  // channel identity + key expression, gated on the row's platform. OR-ed so a
    99	  // multi-platform transcript table is covered without naming any connector.
   100	  const membershipBranch = (
   101	    channelNamespace: string,
   102	    channelKeySql: string,
   103	  ): string => `EXISTS (
   104	          SELECT 1
   105	          FROM public.connections conn
   106	          JOIN public.entity_identities cei
   107	            ON cei.organization_id = ${orgParam}
   108	           AND cei.namespace = '${channelNamespace}'
   109	           AND cei.deleted_at IS NULL
   110	           AND cei.identifier = ${channelKeySql}
   111	          JOIN public.entity_relationships rr
   112	            ON rr.organization_id = ${orgParam}
   113	           AND rr.to_entity_id = cei.entity_id
   114	           AND rr.deleted_at IS NULL
   115	          JOIN public.entity_relationship_types rt
   116	            ON rt.id = rr.relationship_type_id
   117	           AND rt.organization_id = rr.organization_id
   118	           AND rt.slug = 'member_of'
   119	          WHERE conn.organization_id = ${orgParam}
   120	            AND conn.slug IN (${tableAlias}.connection_id, 'agentconn-' || ${tableAlias}.connection_id)
   121	            AND rr.from_entity_id = ${requesterMemberSubquery}
   122	        )`;
   123	
   124	  const platformBranches = identities.map((identity) => {
   125	    const keySql = identity.channelKeySql(teamExpr, `${tableAlias}.channel_id`);
   126	    return `(${tableAlias}.platform = '${identity.platform}' AND ${membershipBranch(
   127	      identity.channelNamespace,
   128	      keySql,
   129	    )})`;
   130	  });
   131	  // No registered chat platform → nothing is member-visible; only the
   132	  // not-graphed passthrough can match. FALSE keeps the enforced branch closed.
   133	  const memberVisible = platformBranches.length > 0 ? platformBranches.join('\n        OR ') : 'FALSE';
   134	
   135	  // Fail-closed on stale: a connection is visible ONLY when it has NO acl state
   136	  // row at all (never onboarded → legacy fence, org-visible) OR it is
   137	  // full+fresh-enforced AND the requester is a channel member. A connection whose
   138	  // acl row EXISTS but isn't currently fresh-enforcing (stale / partial / failed)
   139	  // matches neither branch → its transcripts are dropped. This mirrors
   140	  // getConnectionEnforcement's `not-graphed` (passthrough) vs `stale` (fail
   141	  // closed) split — NOT a bare `NOT IN (enforced)`, which would leak a channel
   142	  // whose ACL snapshot merely aged out.
   143	  const sql = `AND (
   144	      NOT EXISTS (
   145	        SELECT 1 FROM public.authz_source_acl_state a
   146	        WHERE a.organization_id = ${orgParam}
   147	          AND a.connection_id = ${tableAlias}.connection_id
   148	      )
   149	      OR (
   150	        ${tableAlias}.connection_id IN (${enforcedConnectionsSelectSql(orgParam)})
   151	        AND (
   152	          ${memberVisible}
   153	        )
   154	      )
   155	    )`;
   156	  return { sql, params: [scope.organizationId, scope.principal] };
   157	}
     1	/**
     2	 * AuthzScope — the single value every read seam compiles its scoping predicate
     3	 * from. M1 introduces the type and routes the existing per-user
     4	 * connection-visibility logic through one compiler (see ./connection-visibility);
     5	 * later milestones grow `principal` into a verified `$member` (M3) and put
     6	 * `policyVersion` to work (M2/M6). No behavior change at M1: `principal` is the
     7	 * requesting user id and `null` means a headless/service caller (org-visible
     8	 * rows only, fail-closed for private data).
     9	 */
    10	export interface AuthzScope {
    11	  /** The tenant. Every read is partitioned by this first. */
    12	  organizationId: string;
    13	  /**
    14	   * The requesting principal. Today the user id; M3 resolves it to a verified
    15	   * `$member`. `null` = headless/service caller — private data is excluded
    16	   * (fail-closed); only org-visible rows are returned.
    17	   */
    18	  principal: string | null;
    19	  /** The durable agent identity when the read happens inside an agent run. */
    20	  agentId?: string | null;
    21	  /**
    22	   * True when the principal holds owner/admin in the org. Must come from a
    23	   * server-side role check (`callerIsAdmin` / `getWorkspaceRole`), never from
    24	   * client input. Honored only by `compileConnectionRowVisibility`, where it
    25	   * additionally exposes LEGACY-UNOWNED private connections (`created_by IS
    26	   * NULL` rows predating the column) — it does NOT bypass another member's
    27	   * private connections, and the FK (events/content) form ignores it.
    28	   */
    29	  principalIsAdmin?: boolean;
    30	  /** Policy snapshot the read is compiled against. Reserved for M2+/M6. */
    31	  policyVersion?: number | null;
    32	}
    33	
    34	/**
    35	 * Build an AuthzScope from a tool/SDK execution context. The `ToolContext`
    36	 * carries `userId: string | null` (the requesting user, null when anonymous /
    37	 * headless) plus the durable `agentId` — exactly the inputs the scope needs.
    38	 */
    39	export function authzScopeFromToolContext(ctx: {
    40	  organizationId: string;
    41	  userId: string | null;
    42	  agentId?: string | null;
    43	}): AuthzScope {
    44	  return {
    45	    organizationId: ctx.organizationId,
    46	    principal: ctx.userId,
    47	    agentId: ctx.agentId ?? null,
    48	  };
    49	}
    50	
    51	/**
    52	 * A headless/service scope: no principal, so only org-visible rows are returned
    53	 * (fail-closed for private data). Use for watchers / scheduled jobs / internal
    54	 * reads that run without a requesting user.
    55	 */
    56	export function headlessScope(organizationId: string): AuthzScope {
    57	  return { organizationId, principal: null };
    58	}


