   116	 * entity id, or null when the key cannot be formed (e.g. a chat connector whose
   117	 * team-scoped key needs a team id that wasn't supplied).
   118	 */
   119	export async function ensureChannelResourceEntity(opts: {
   120		organizationId: string;
   480			connectorKey: opts.connectorKey,
   481			teamId: opts.teamId,
   482			channelId: bareChannelId,
   483			sql,
   484		});
   485		if (channelEntityId === null) return [];
   486		const ids = await listChannelAboutEntityIds({
   487			organizationId: opts.organizationId,
   488			channelEntityId,
   489			sql,
   490		});
   491		if (ids.length === 0) return [];
   492		const rows = await sql<{ id: number; name: string; slug: string | null }>`
   493	    SELECT id, name, slug
   494	    FROM entities
   495	    WHERE organization_id = ${opts.organizationId}
   496	      AND id = ANY(${pgBigintArray(ids)}::bigint[])
   497	      AND deleted_at IS NULL
   498	    ORDER BY name NULLS LAST, id
   499	  `;
   500		return rows.map((r) => ({
   501			id: Number(r.id),
   502			name: r.name,
   503			slug: r.slug,
   504		}));
   505	}
   506	
   507	/** Business entity ids linked to a channel via `about` (any source). */
   508	export async function listChannelAboutEntityIds(opts: {
   509		organizationId: string;
   510		channelEntityId: number;
   511		sql?: DbClient;
   512	}): Promise<number[]> {
   513		const sql = opts.sql ?? getDb();
   514		const typeId = await findAboutRelationshipTypeId(opts.organizationId, sql);
   515		if (typeId === null) return [];
   516		const rows = await sql<{ to_entity_id: number }>`
   517	    SELECT r.to_entity_id
   518	    FROM entity_relationships r
   519	    WHERE r.organization_id = ${opts.organizationId}
   520	      AND r.from_entity_id = ${opts.channelEntityId}
   521	      AND r.relationship_type_id = ${typeId}
   522	      AND r.deleted_at IS NULL
   523	    ORDER BY r.to_entity_id
