   528	/** Reverse lookup: channel resource entities with an `about` edge to a business entity. */
   529	export async function listChannelEntitiesAboutBusinessEntity(opts: {
   530		organizationId: string;
   531		businessEntityId: number;
   532		sql?: DbClient;
   533	}): Promise<
   534		Array<{
   535			channelEntityId: number;
   536			channelName: string | null;
   537			connectionId: string | null;
   538			channelKey: string | null;
   539		}>
   540	> {
   541		const sql = opts.sql ?? getDb();
   542		const typeId = await findAboutRelationshipTypeId(opts.organizationId, sql);
   543		if (typeId === null) return [];
   544		const rows = await sql<{
   545			channel_entity_id: number;
   546			channel_name: string | null;
   547			connection_id: string | null;
   548			channel_key: string | null;
   549		}>`
   550	    SELECT
   551	      r.from_entity_id AS channel_entity_id,
   552	      e.name AS channel_name,
   553	      r.metadata->>'connection_id' AS connection_id,
   554	      r.metadata->>'channel_key' AS channel_key
   555	    FROM entity_relationships r
   556	    JOIN entities e
   557	      ON e.id = r.from_entity_id
   558	     AND e.organization_id = r.organization_id
   559	     AND e.deleted_at IS NULL
   560	    WHERE r.organization_id = ${opts.organizationId}
   561	      AND r.to_entity_id = ${opts.businessEntityId}
   562	      AND r.relationship_type_id = ${typeId}
   563	      AND r.deleted_at IS NULL
   564	    ORDER BY e.name NULLS LAST, r.from_entity_id
   565	  `;
   566		return rows.map((r) => ({
   567			channelEntityId: Number(r.channel_entity_id),
   568			channelName: r.channel_name,
   569			connectionId: r.connection_id,
   570			channelKey: r.channel_key,
   571		}));
   572	}
   573	
   574	/** Channel key stored on `about` edge metadata for a streaming feed row.
   575	 *
   576	 * The team half is the channel's CONCRETE workspace, taken from the streaming
   577	 * feed's Behavior subscription team — the SAME real team the
   578	 * about-edge writer keyed on. For a Grid org-wide install the connection's
   579	 * `external_tenant_id` is the enterprise `E…`, so it must NOT be used as the
   580	 * team; the subscription holds the real `T…`. The `external_tenant_id` fallback
   581	 * supports connectors whose tenant identity is their workspace. A not-yet-healed
   582	 * Grid subscription has no matching about edge until its concrete team is known.
   583	 * The subscription channel id equals feed_key, so the correlation is exact. */
   584	export function streamingFeedChannelKeyExpr(
   585		feedAlias = "f",
   586		connectionAlias = "c",
   587	): string {
   588		return `UPPER(
   589	    COALESCE(
   590	      (
   591	        SELECT subscription.trigger_team_id
   592	        FROM behavior_message_subscriptions subscription
   593	        WHERE subscription.organization_id = ${feedAlias}.organization_id
   594	          AND subscription.connection_id = ${feedAlias}.connection_id
   595	          AND subscription.channel_id = ${feedAlias}.feed_key
   596	          AND subscription.trigger_team_id IS NOT NULL
   597	        LIMIT 1
   598	      ),
   599	      ${connectionAlias}.external_tenant_id,
   600	      ''
   601	    ) || ':' ||
   602	    CASE
   603	      WHEN ${feedAlias}.feed_key LIKE '%:%'
   604	        THEN split_part(${feedAlias}.feed_key, ':', 2)
   605	      ELSE ${feedAlias}.feed_key
   606	    END
   607	  )`;
   608	}
