   614	export function feedLinkedToBusinessEntitySql(
   615		entityIdExpr: string,
   616		feedAlias = "f",
   617		connectionAlias = "c",
   618		orgIdExpr?: string,
   619	): string {
   620		const org = orgIdExpr ?? `${feedAlias}.organization_id`;
   621		const tagMatch = `${entityIdExpr} = ANY(${feedAlias}.entity_ids)`;
   622		const aboutMatch = `(
   623	    ${feedAlias}.kind = 'streaming'
   624	    AND EXISTS (
   625	      SELECT 1
   626	      FROM entity_relationships r
   627	      JOIN entity_relationship_types rt
   628	        ON rt.id = r.relationship_type_id
   629	       AND rt.organization_id = r.organization_id
   630	       AND rt.slug = '${ABOUT_RELATIONSHIP_SLUG}'
   631	       AND rt.status = 'active'
   632	      WHERE r.organization_id = ${org}
   633	        AND r.to_entity_id = ${entityIdExpr}
   634	        AND r.deleted_at IS NULL
   635	        AND r.metadata->>'connection_id' = ${feedAlias}.connection_id::text
   636	        AND r.metadata->>'channel_key' = ${streamingFeedChannelKeyExpr(feedAlias, connectionAlias)}
   637	    )
   638	  )`;
   639		return `(${tagMatch} OR ${aboutMatch})`;
   640	}
