   663	export function connectionLinkedEntityIdsSql(connectionAlias = "c"): string {
   664		return `(
   665	    SELECT unnest(${connectionAlias}.entity_ids)
   666	    UNION
   667	    SELECT unnest(f.entity_ids)
   668	    FROM feeds f
   669	    WHERE f.connection_id = ${connectionAlias}.id
