   486				// LEFT JOIN into an effective inner filter (runs with no watcher, i.e.
   487				// bare syncs/actions, are dropped — they aren't agent-owned).
   488				const agentFilter = opts.agentId
   489					? sql`AND w.agent_id = ${opts.agentId}`
   490					: sql``;
   491				const rows = (await sql`
   492	        SELECT r.id, r.run_type, r.watcher_id, r.connection_id, r.feed_id,
   493	               r.connector_key, r.action_key AS operation_key,
   494	               r.approval_status, r.status, r.error_message, r.items_collected,
   495	               r.created_at, r.completed_at,
   496	               f.feed_key, f.display_name AS feed_display_name,
   497	               c.display_name AS connection_display_name,
   498	               w.name AS watcher_name, w.agent_id
   499	        FROM runs r
