   507	        LIMIT 60
   508	      `) as unknown as Array<{
   509					id: number;
   510					run_type: string;
   511					watcher_id: number | null;
   512					connection_id: number | null;
   513					feed_id: number | null;
   514					connector_key: string | null;
   515					operation_key: string | null;
   516					approval_status: string | null;
   517					status: string;
   518					error_message: string | null;
   519					items_collected: number | null;
   520					created_at: string | Date;
   521					feed_key: string | null;
   522					feed_display_name: string | null;
   523					connection_display_name: string | null;
   524					watcher_name: string | null;
   525					agent_id: string | null;
   526				}>;
   527	
   528				for (const r of rows) {
   529					const created =
   530						r.created_at instanceof Date
   531							? r.created_at.toISOString()
   532							: String(r.created_at);
   533					const atMs = new Date(created).getTime();
   534					const kind =
   535						r.run_type === "behavior"
   536							? "behavior_run"
   537							: r.run_type === "sync"
   538								? "sync"
   539								: "run";
   540					const body = r.error_message
   541						? r.error_message.slice(0, 120)
   542						: r.items_collected != null
   543							? `${r.status} · ${r.items_collected} items`
   544							: r.status;
