   546						id: `r:${r.id}`,
   547						kind,
   548						title: runTitle(r),
   549						body,
   550						at: created,
   551						atMs: Number.isFinite(atMs) ? atMs : 0,
   552						status: r.status,
   553						count: 1,
   554						href: runHref(opts.ownerSlug, r),
   555						run_id: r.id,
   556						connection_id: r.connection_id ?? undefined,
   557						behavior_id: r.watcher_id ?? undefined,
   558						collapseKey: collapseKeyForRun(r),
   559						itemsCollected: r.items_collected,
   560					});
   561				}
   562			}
   563		}
   564	
   565		// Newest window → chronological → optional adjacent collapse → cap.
   566		raw.sort((a, b) => b.atMs - a.atMs);
   567		const windowed = raw.slice(0, 60);
   568		windowed.reverse();
   569		const collapsed = aggregate
   570			? collapseAdjacentActivityCards(windowed)
   571			: windowed;
   572		const items = collapsed.slice(-limit).map(({ collapseKey, itemsCollected, atMs, ...card }) => card);
   573	
   574		return { items, total: items.length, limit };
   575	}
   576	
   577	/** Drop the query string + fragment from a deep-link (absolute or relative).
   578	 * Notification hrefs can carry OAuth authorization codes and invitation ids as
   579	 * query params; those must never reach worker context. Kept out of the UI path
   580	 * on purpose: listOrgActivity still returns full hrefs for the trusted client. */
   581	function stripUrlParams(url: string): string {
   582		const cut = url.search(/[?#]/);
   583		return cut >= 0 ? url.slice(0, cut) : url;
   584	}
   585	
   586	/** Redact query strings from any URL embedded in free-form body text, so a
   587	 * notification body like "re-auth here: https://…?code=…" cannot smuggle a
   588	 * credential into worker context. */
   589	function redactBodyUrls(text: string): string {
   590		return text.replace(/(https?:\/\/[^\s?#]+)[^\s]*/g, "$1");
   591	}
   592	
   593	/**
   594	 * Compact prompt block for first-turn agent context (≤ ~2k chars).
   595	 *
   596	 * This feeds worker `ephemeralContext`, an untrusted-prompt surface, so it
   597	 * emits an allowlisted, worker-safe projection only: query params are stripped
   598	 * from links and body URLs (OAuth codes, invitation ids), and titles, errors,
   599	 * and names are forwarded solely as sanitized untrusted text.
   600	 */
   601	export function formatActivityAttentionBlock(
   602		items: ActivityCard[],
   603		maxLines = 10,
   604	): string {
   605		if (items.length === 0) return "";
   606		const lines: string[] = ["## Workspace attention (recent)"];
   607		const slice = items.slice(-maxLines);
   608		for (const it of slice) {
   609			const status = it.status ? ` [${it.status}]` : "";
   610			const count = it.count > 1 ? ` ×${it.count}` : "";
   611			const body = it.body
   612				? ` — ${redactBodyUrls(it.body).replace(/\s+/g, " ").slice(0, 120)}`
   613				: "";
   614			const href = it.href ? ` (${stripUrlParams(it.href)})` : "";
   615			let line = `- ${it.title}${count}${status}${body}${href}`;
   616			// Sanitize control chars like buildRunContextBlock
   617			line = [...line]
   618				.map((ch) => {
   619					const code = ch.codePointAt(0) ?? 0;
   620					return code < 0x20 || (code >= 0x7f && code <= 0x9f) ? " " : ch;
   621				})
   622				.join("")
   623				.replace(/\s+/g, " ")
   624				.trim()
   625				.slice(0, 280);
   626			if (line.length > 2) lines.push(line);
   627		}
   628		const block = lines.join("\n");
   629		return block.length > 2000 ? block.slice(0, 2000) : block;
   630	}

