  1	/**
  2	 * Connection facet derivation — the ONE place a connection's roles are computed.
  3	 *
  4	 * A connection is a single `connections` row, but it can play several roles at
  5	 * once depending on what the connector + config enable. These "facets" are
  6	 * DERIVED (never stored), so they stay correct as feeds/operations/membership
  7	 * change. Keeping the derivation in one helper (shared by list / get /
  8	 * connector-groups) means the chips on the index, the connection page, and the
  9	 * group cards can never drift apart.
 10	 *
 11	 *   - data     — ingests external data into memory (feeds → events)
 12	 *   - chat     — the agent converses through it (a live bot adapter; the
 13	 *                Stage-2a `credential_mode` marker is set)
 14	 *   - actions  — exposes operations the agent can invoke (MCP tools / writes)
 15	 *   - audience — read access is gated by the source's own membership (ACL)
 16	 */
 17	
 18	import { ACL_SOURCES } from '../../../../authz/sources';
 19	
 20	/** Connector keys whose data is access-controlled by source membership. */
 21	const AUDIENCE_CONNECTOR_KEYS = new Set(ACL_SOURCES.map((s) => s.key));
 22	
 23	export interface ConnectionFacets {
 24	  data: boolean;
 25	  chat: boolean;
 26	  actions: boolean;
 27	  audience: boolean;
 28	}
 29	
 30	export function deriveConnectionFacets(input: {
 31	  connectorKey: string;
 32	  /** A live bot adapter (the Stage-2a `credential_mode` marker is set). For a
 33	   *  connector group, true when ANY member connection is a chat connection. */
 34	  isChat: boolean;
 35	  /** Number of live feeds bound to this connection (or group). */
 36	  feedCount: number;
 37	  /** Whether the connector declares a non-empty `feeds_schema` (data-capable). */
 38	  connectorHasFeeds: boolean;
 39	  /** Whether the connector exposes any invocable operations. */
 40	  hasOperations: boolean;
 41	}): ConnectionFacets {
 42	  return {
 43	    data: input.feedCount > 0 || input.connectorHasFeeds,
 44	    chat: input.isChat,
 45	    actions: input.hasOperations,
 46	    audience: AUDIENCE_CONNECTOR_KEYS.has(input.connectorKey),
 47	  };
 48	}
 49	
 50	/**
 51	 * The credential-mode badge: managed (Lobu-hosted OAuth install) vs byo (you
 52	 * supplied the credentials). Chat connections carry it explicitly in
 53	 * `credential_mode`; for data connectors we infer it from the auth profile —
 54	 * an OAuth app install (`app_auth_profile_id`) is managed, any other configured
 55	 * auth is byo, and a connection with no auth concept returns null.
 56	 */
 57	export function deriveEffectiveCredentialMode(input: {
 58	  credentialMode: string | null | undefined;
 59	  appAuthProfileId: unknown;
 60	  authProfileId: unknown;
 61	}): 'managed' | 'byo' | null {
 62	  if (input.credentialMode === 'managed' || input.credentialMode === 'byo') {
 63	    return input.credentialMode;
 64	  }
 65	  if (input.appAuthProfileId != null) return 'managed';
 66	  if (input.authProfileId != null) return 'byo';
 67	  return null;
 68	}
  1	import type { LucideIcon } from "lucide-react";
