141	/**
142	 * Resolve the requester to a `$member` entity id, combining BOTH paths the
143	 * authz program supports: prefer the auth-server signup claim (web/app sign-in),
144	 * then fall back to the platform's team-scoped user claim for someone talking to
145	 * the bot INSIDE a chat platform (whose only id is a platform user id).
146	 * `enforcingTenants` scopes the chat fallback to the (platform, team) tenants
147	 * whose connections are actually enforcing. Returns null when neither resolves
148	 * (→ fail closed).
149	 *
150	 * The single resolver shared by the gate ({@link filterChannelsForRequester})
151	 * and the audience read's "you" highlight, so the two never disagree on who the
152	 * requester is.
153	 */
154	export async function resolveRequesterMember(
155	  sql: DbClient,
156	  organizationId: string,
157	  userId: string | null,
158	  enforcingTenants: EnforcingTenant[],
159	): Promise<number | null> {
160	  if (!userId) return null;
161	  const byAuth = await resolveRequesterMemberEntityId(sql, organizationId, userId);
162	  if (byAuth !== null) return byAuth;
163	  return resolveRequesterByChatUserId(sql, organizationId, userId, enforcingTenants);
164	}
165	
166	/** Every registered chat-channel identity namespace — the channel resource key
167	 * namespaces the member-visibility read unions over. */
168	const CHANNEL_KEY_NAMESPACES: string[] = [
169	  ...new Set(CHANNEL_READ_IDENTITIES.map((c) => c.channelNamespace)),
170	];
171	
172	/**
173	 * The team-scoped channel keys the member can read, via `member_of` edges to
174	 * `$resource` entities carrying any registered chat-channel identity (Slack:
175	 * `slack_channel_id` = `T…:C…`). Unions across every registered chat platform's
176	 * channel namespace so a member spanning platforms sees all their channels.
177	 */
178	export async function getVisibleChannelKeysForMember(
179	  sql: DbClient,
180	  organizationId: string,
181	  memberEntityId: number,
182	): Promise<Set<string>> {
183	  if (CHANNEL_KEY_NAMESPACES.length === 0) return new Set();
184	  const rows = await sql<{ channel_key: string }>`
185			SELECT ei.identifier AS channel_key
186			FROM entity_relationships r
187			JOIN entity_relationship_types rt
188			  ON rt.id = r.relationship_type_id
189			 AND rt.organization_id = r.organization_id
190			 AND rt.slug = 'member_of'
191			JOIN entity_identities ei
192			  ON ei.entity_id = r.to_entity_id
193			 AND ei.organization_id = r.organization_id
194			 AND ei.namespace = ANY(${pgTextArray(CHANNEL_KEY_NAMESPACES)}::text[])
195			 AND ei.deleted_at IS NULL
196			WHERE r.organization_id = ${organizationId}
197			  AND r.from_entity_id = ${memberEntityId}
198			  AND r.deleted_at IS NULL
199		`;
200	  return new Set(rows.map((r) => String(r.channel_key)));
201	}
202	
203	/**
204	 * Filter bound channels down to what the requester may actually read. By
205	 * default, channels on never-graphed connections preserve legacy access;
206	 * callers granting access to non-owners can disable that fallback. Channels on
207	 * enforced connections survive only when the requester is provably `member_of`
208	 * them. An enforced channel with no team id, or an unresolvable requester, is
209	 * dropped.
210	 *
211	 * Returns the surviving rows (same objects, filtered) — the caller keeps its
212	 * existing per-channel query shape, just over a possibly-smaller set.
213	 */
214	export async function filterChannelsForRequester<T extends GatedChannelRow>(
215	  sql: DbClient,
216	  params: {
217	    organizationId: string;
218	    userId: string | null;
219	    rows: T[];
220	    allowNotGraphed?: boolean;
221	  },
222	): Promise<T[]> {
223	  const { organizationId, userId, rows, allowNotGraphed = true } = params;
224	  if (rows.length === 0) return rows;
225	
  1	/**
  2	 * Shared ACL-enforcement-state helpers — used by BOTH read gates (the Slack
  3	 * channel gate `./channel-visibility` and the generic resource gate
  4	 * `./resource-visibility`) AND the audience read (`./audience`) so the "is this
  5	 * connection enforcing right now?" rule and the team-scoped channel key live in
  6	 * one place and cannot drift between them.
  7	 */
  8	
  9	import { type DbClient, pgTextArray } from "../db/client.js";
 10	import { stripPlatformPrefix } from "../gateway/channels/bound-channels.js";
 11	import { channelReadIdentityFor } from "./sources.js";
 12	
 13	/**
 14	 * How long a `fresh` ACL graph stays trusted without a re-sync. The background
 15	 * sync re-stamps `last_synced_at`; if it stops, a connection's graph ages past
 16	 * this window and the gate stops trusting it — failing closed rather than
 17	 * serving stale membership. Generous vs. the ~15-min sync cadence so a transient
 18	 * hiccup never blinks recall off.
 19	 */
 20	export const ACL_STALE_AFTER_MINUTES = 60;
 21	
 22	/**
 23	 * SQL subquery (no leading/trailing space) selecting the `connection_id`s that
 24	 * are ACL-enforced right now: `acl_support='full'` AND `freshness_state='fresh'`
 25	 * AND synced within {@link ACL_STALE_AFTER_MINUTES}. `orgParam` is an already-bound
 26	 * `$N::text` placeholder. Returns the bare `SELECT …` (caller wraps in IN/NOT IN).
 27	 */
 28	export function enforcedConnectionsSelectSql(orgParam: string): string {
 29	  return `SELECT connection_id FROM public.authz_source_acl_state
 30	    WHERE organization_id = ${orgParam}
 31	      AND acl_support = 'full'
 32	      AND freshness_state = 'fresh'
 33	      AND last_synced_at IS NOT NULL
 34	      AND last_synced_at >= current_timestamp - make_interval(mins => ${ACL_STALE_AFTER_MINUTES})`;
 35	}
 36	
 37	/**
 38	 * SQL subquery (no leading/trailing space) selecting the `connection_id`s that
 39	 * have ANY `authz_source_acl_state` row — i.e. every connection ONBOARDED into
 40	 * authz, regardless of whether it is currently enforcing. The complement
 41	 * (`NOT IN` this set) is the "never graphed → legacy fence" case; a connection
 42	 * that IS in this set but NOT in {@link enforcedConnectionsSelectSql} is
 43	 * onboarded-but-stale and must fail closed. `orgParam` is an already-bound
 44	 * `$N::text` placeholder. Returns the bare `SELECT …` (caller wraps in IN/NOT IN).
 45	 */
